            analysis['immediate_action_required'].append({
                'package': vuln['package'],
                'severity': severity,
                'action': f"Update to {vuln['patched_versions']}"
            })

    # Sort by risk score
    for severity in analysis['by_severity']:
        analysis['by_severity'][severity].sort(
